create sequence if not exists sales_receipt_number_seq;
create table sales_receipts (id bigint generated by default as identity primary key, tenant_id bigint not null references tenants(id), company_id bigint not null references companies(id), branch_id bigint not null references branches(id), customer_id bigint not null references customers(id), receipt_number varchar(64) not null, payment_date timestamptz not null, amount numeric(18,2) not null, payment_method varchar(32) not null, reference varchar(160), treasury_transaction_id bigint references treasury_transactions(id), status varchar(16) not null default 'DRAFT', idempotency_key varchar(160) not null, created_at timestamptz not null default now(), confirmed_at timestamptz, version bigint not null default 0, constraint sales_receipts_amount_ck check(amount>0), constraint sales_receipts_status_ck check(status in ('DRAFT','CONFIRMED','CANCELLED')), unique(tenant_id,idempotency_key), unique(tenant_id,receipt_number));
create table sales_receipt_allocations (id bigint generated by default as identity primary key, tenant_id bigint not null references tenants(id), receipt_id bigint not null references sales_receipts(id), sales_invoice_id bigint not null references sales_invoices(id), amount numeric(18,2) not null, unique(receipt_id,sales_invoice_id), constraint sales_receipt_alloc_amount_ck check(amount>0));
create index sales_receipts_scope_idx on sales_receipts(tenant_id,company_id,branch_id,customer_id);
